window.EditorTools=(()=>{
let current=null,panel=null;
const el=(tag,text)=>{const n=document.createElement(tag);if(text)n.textContent=text;return n};
async function open(kind,q){
 if(panel){if(!confirm('Discard the open proposal form?'))return;panel.remove();}
 panel=el('section');panel.className='editor-inline';document.getElementById('editor-actions').after(panel);const box=panel;box.textContent='Loading current bank version…';
 try{const data=await Account.request('/api/editor/content?kind='+kind+'&id='+encodeURIComponent(kind==='case'?q.case_id:q.id));if(panel!==box)return;box.replaceChildren();box.append(el('h2',kind==='case'?'Edit shared scenario':'Edit question'),el('p','Editing the current bank version. Your saved attempt remains unchanged. Submit a proposal for admin approval.'));const form=el('form'),inputs={};
 function field(key,label,value){const l=el('label',label),t=el('textarea');t.value=value||'';t.rows=key.startsWith('choice:')?3:10;t.maxLength=key.startsWith('choice:')?5000:20000;l.append(t);form.append(l);inputs[key]=t;window.attachTextFormatting?.(t);}
 if(kind==='question'){field('text','Question text',data.body.text);for(const c of data.body.choices||[])field('choice:'+c.id,'Choice '+c.id,c.text);field('explanation','Explanation shown after submission',data.body.explanation)}else for(const [k,l] of [['title','Case title'],['history','History'],['examination','Physical examination'],['laboratory','Laboratory findings']])field(k,l,data.body[k]);
 const preview=el('button','Preview proposal'),save=el('button','Submit for admin approval'),cancel=el('button','Cancel'),status=el('p'),rendered=el('div');preview.type=cancel.type='button';save.type='submit';preview.className=cancel.className='secondary';save.className='primary';status.setAttribute('role','status');
 preview.onclick=()=>{rendered.replaceChildren();for(const [k,t] of Object.entries(inputs)){rendered.append(el('h3',k.startsWith('choice:')?'Choice '+k.slice(7):k));const v=el('div');if(window.RichText)v.innerHTML=RichText.render(t.value);else v.textContent=t.value;rendered.append(v)}};
 cancel.onclick=()=>{box.remove();panel=null};form.onsubmit=async e=>{e.preventDefault();save.disabled=true;try{const fields={};for(const [k,t] of Object.entries(inputs))if(!k.startsWith('choice:'))fields[k]=t.value;if(kind==='question')fields.choices=(data.body.choices||[]).map(c=>({id:c.id,text:inputs['choice:'+c.id].value}));const r=await Account.request('/api/editor/propose',{kind,id:kind==='case'?q.case_id:q.id,revision:data.revision,fields});box.replaceChildren(el('p','Proposal #'+r.saved+' submitted for admin approval. Published content and this attempt are unchanged.'));panel=null;}catch(e){status.textContent=e.message;save.disabled=false}};form.append(preview,save,cancel,status,rendered);box.append(form);
 }catch(e){box.textContent=e.message;panel=null;}
}
function show(q){Account.ready.then(user=>{if(!['editor','admin'].includes(user.role))return;if(current!==q.id){panel?.remove();panel=null;current=q.id;}let bar=document.getElementById('editor-actions');if(!bar){bar=el('section');bar.id='editor-actions';document.getElementById('question').before(bar);}const info=el('p');info.className='editor-preview-info';const label=el('strong','Editor preview'),badge=el('span',q.status||'Published'),code=el('span',q.display_code||q.id);badge.className='editor-status';badge.dataset.status=q.status||'Published';code.className='editor-code';info.append(label,badge,code);bar.replaceChildren(info);const b=el('button','Edit question');b.className='secondary';b.onclick=()=>open('question',q);bar.append(b);if(q.case_id){const c=el('button','Edit shared scenario');c.className='secondary';c.onclick=()=>open('case',q);bar.append(c);}})}
const css=el('style');css.textContent='.editor-inline,#editor-actions{padding:20px;margin:16px 0;background:#f4f7ff;border:1px solid #bccbe8;border-radius:12px}.editor-inline label{display:block;margin:16px 0}.editor-inline textarea{display:block;box-sizing:border-box;width:100%;font:inherit;padding:12px;resize:vertical}.editor-inline button,#editor-actions button{margin:6px}.editor-inline div{white-space:normal}';document.head.append(css);
window.addEventListener('beforeunload',e=>{if(panel?.querySelector('form')){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',e=>{if(panel?.querySelector('form')&&e.target.closest('#next,#back,#navigator button,a[href]')&&!confirm('Discard the open proposal form?')){e.preventDefault();e.stopImmediatePropagation();}},true);
return {show};})();
